package com.fixmer.genesis.technology.server.remote;
import com.fixmer.genesis.technology.server.firstlaunch.*;
import com.fixmer.genesis.technology.server.packages.*;
import java.io.*;import java.net.*;import javax.net.ssl.HttpsURLConnection;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.function.BooleanSupplier;import java.util.zip.ZipFile;
/** Fresh signed pre-login state. No Minecraft login bypass, identity assertion, or PID authority. */
public final class Bootstrap76 {
 private Bootstrap76(){}
 public record State(Map<String,String> values,RemoteOffer69 offer,byte[] key,byte[] signature){public State{values=Map.copyOf(values);key=key.clone();signature=signature.clone();}public byte[] key(){return key.clone();}public byte[] signature(){return signature.clone();}public String phase(){return values.get("phase");}}
 public static final Set<String> FIELDS=Set.of("schema","owner","generation","phase","serial","issued","expires","game","endpoint","distribution","release","archive","signer","minecraft","neoforge","inventory","offer","offerSig");
 public static byte[] get(URI uri,int max,BooleanSupplier cancel)throws IOException{
  if(!uri.getScheme().equals("https"))throw new IOException("BOOTSTRAP76_TLS");HttpsURLConnection c=(HttpsURLConnection)uri.toURL().openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(5000);c.setUseCaches(false);c.setRequestProperty("Accept-Encoding","identity");
  try{if(cancel.getAsBoolean())throw new InterruptedIOException("REMOTE_CANCELLED");if(c.getResponseCode()!=200)throw new IOException("BOOTSTRAP76_UNAVAILABLE");String encoding=c.getHeaderField("Content-Encoding");if(encoding!=null&&!encoding.equalsIgnoreCase("identity")||c.getContentLengthLong()>max)throw new IOException("BOOTSTRAP76_SIZE");try(var in=c.getInputStream()){byte[] data=in.readNBytes(max+1);if(data.length>max||c.getContentLengthLong()>=0&&data.length!=c.getContentLengthLong())throw new IOException("BOOTSTRAP76_SIZE");if(cancel.getAsBoolean())throw new InterruptedIOException("REMOTE_CANCELLED");return data;}}finally{c.disconnect();}
 }
 public static State verify(byte[] packet,byte[] key,String game,String endpoint,String mc,String neo,long now)throws Exception{
  var d=ControlWire73.verify(RemoteOffer69.publicKey(key),packet);if(!d.keySet().equals(FIELDS)||!d.get("schema").equals("76"))throw new IOException("BOOTSTRAP76_STATE");
  if(!UUID.fromString(d.get("owner")).toString().equals(d.get("owner"))||UUID.fromString(d.get("owner")).equals(new UUID(0,0))||!d.get("generation").matches("[1-9][0-9]?")||Integer.parseInt(d.get("generation"))>32||!Set.of("TRANSITION","READY","UNAVAILABLE").contains(d.get("phase"))||!d.get("serial").matches("[1-9][0-9]{0,17}")||!d.get("inventory").matches("[a-f0-9]{64}"))throw new IOException("BOOTSTRAP76_STATE");
  long issued=Long.parseLong(d.get("issued")),expires=Long.parseLong(d.get("expires"));if(issued<1||issued>now+30000||expires<=issued||expires-issued>10000||expires<now)throw new IOException("BOOTSTRAP76_STALE");
  var offer=RemoteOffer69.decode(Base64.getDecoder().decode(d.get("offer")));byte[] sig=Base64.getDecoder().decode(d.get("offerSig"));offer.verify(RemoteOffer69.publicKey(key),sig);
  if(!RemoteOffer69.gameAddress(game).equals(d.get("game"))||!RemoteOffer69.base(endpoint).equals(d.get("endpoint"))||!mc.equals(d.get("minecraft"))||!neo.equals(d.get("neoforge"))||!offer.game().equals(d.get("game"))||!offer.endpoint().equals(d.get("endpoint"))||!offer.distribution().toString().equals(d.get("distribution"))||!offer.release().toString().equals(d.get("release"))||!offer.archiveSha().equals(d.get("archive"))||!offer.signer().equals(d.get("signer"))||!offer.signer().equals(FirstLaunchFiles.sha(key))||!offer.minecraft().equals(mc)||!offer.neoforge().equals(neo))throw new IOException("BOOTSTRAP76_BINDING");offer.validAt(now);return new State(d,offer,key,sig);
 }
 public static State inspect(String game,String endpoint,String mc,String neo,BooleanSupplier cancel)throws Exception{
  endpoint=RemoteOffer69.base(endpoint);byte[] key=get(URI.create(endpoint+"public.der"),256,cancel);return verify(get(URI.create(endpoint+"bootstrap76/state"),32768,cancel),key,game,endpoint,mc,neo,System.currentTimeMillis());
 }
 public static void same(State expected,State current)throws IOException{
  if(expected.values.get("serial").equals(current.values.get("serial"))&&!expected.values.equals(current.values))throw new IOException("BOOTSTRAP76_EQUIVOCATION");
  for(String k:List.of("owner","generation","game","endpoint","distribution","release","archive","signer","inventory"))if(!expected.values.get(k).equals(current.values.get(k)))throw new IOException("BOOTSTRAP76_CHANGED");if(Long.parseLong(current.values.get("serial"))<Long.parseLong(expected.values.get("serial"))||current.phase().equals("UNAVAILABLE"))throw new IOException("BOOTSTRAP76_CHANGED");
 }
 public static final Set<String> CONFIG=Set.of("schema","owner","generation","release","archive","game","endpoint","distribution","signer","inventory","serial");
 public static Map<String,String> config(Path directory)throws IOException{var c=ControlWire73.decode(FirstLaunchFiles.read(directory.resolve("bootstrap76.cfg"),16384));if(!c.keySet().equals(CONFIG)||!c.get("schema").equals("76")||!RemoteOffer69.gameAddress(c.get("game")).equals(c.get("game"))||!RemoteOffer69.base(c.get("endpoint")).equals(c.get("endpoint")))throw new IOException("BOOTSTRAP76_CONFIG");for(String k:List.of("owner","release","distribution"))if(!UUID.fromString(c.get(k)).toString().equals(c.get(k)))throw new IOException("BOOTSTRAP76_CONFIG");for(String k:List.of("archive","signer","inventory"))if(!c.get(k).matches("[a-f0-9]{64}"))throw new IOException("BOOTSTRAP76_CONFIG");if(!c.get("generation").matches("[1-9][0-9]?")||Integer.parseInt(c.get("generation"))>32||!c.get("serial").matches("[1-9][0-9]{0,17}"))throw new IOException("BOOTSTRAP76_CONFIG");return c;}
 public static void mark(RemoteClient69.Download download,State state)throws IOException{if(!download.offer().release().equals(state.offer.release())||!download.offer().archiveSha().equals(state.offer.archiveSha()))throw new IOException("BOOTSTRAP76_CHANGED");var c=new TreeMap<String,String>();for(String k:CONFIG)c.put(k,state.values.get(k));FirstLaunchFiles.write(download.directory().resolve("bootstrap76.cfg"),ControlWire73.encode(c),false);}
 public static State pollCandidate(Path directory,String mc,String neo,BooleanSupplier cancel)throws Exception{var c=config(directory);var state=inspect(c.get("game"),c.get("endpoint"),mc,neo,cancel);for(String k:List.of("owner","generation","release","archive","game","endpoint","distribution","signer","inventory"))if(!c.get(k).equals(state.values.get(k)))throw new IOException("BOOTSTRAP76_CHANGED");if(Long.parseLong(state.values.get("serial"))<Long.parseLong(c.get("serial"))||state.phase().equals("UNAVAILABLE"))throw new IOException("BOOTSTRAP76_CHANGED");return state;}
 public static State checkCandidate(Path directory,String mc,String neo,BooleanSupplier cancel)throws Exception{var state=pollCandidate(directory,mc,neo,cancel);var verified=PackageArchive.verify(directory.resolve("client.zip"),Map.of(state.offer.signer(),RemoteOffer69.publicKey(state.key)),new PackageModel.Target(state.offer.distribution(),PackageModel.Side.CLIENT,mc,neo,1));if(!verified.manifest().release().equals(state.offer.release())||!Objects.equals(verified.manifest().parent(),state.offer.parent())||!FirstLaunchFiles.hash(directory.resolve("client.zip"),PackageModel.MAX_ARCHIVE).equals(state.offer.archiveSha())||Files.size(directory.resolve("client.zip"))!=state.offer.bytes()||!inventory(verified).equals(state.values.get("inventory")))throw new IOException("BOOTSTRAP76_INVENTORY");return state;}
 public static String inventory(PackageArchive.Verified archive)throws IOException{return manifestInventory(archive.manifest());}
 public static String manifestInventory(PackageModel.Manifest manifest)throws IOException{
  var rows=new TreeMap<String,String>();for(var f:manifest.files()){if(f.side()!=PackageModel.Side.CLIENT||!f.path().startsWith("mods/")||rows.put(f.path(),f.sha256())!=null)throw new IOException("BOOTSTRAP76_INVENTORY");}StringBuilder text=new StringBuilder();rows.forEach((p,h)->text.append(p).append('=').append(h).append('\n'));return FirstLaunchFiles.sha(text.toString().getBytes(StandardCharsets.US_ASCII));
 }
 public static boolean runtimeMatches(State state,Path profile,Collection<Path> loaded,String mc,String neo)throws IOException{return state.phase().equals("READY")&&state.offer.minecraft().equals(mc)&&state.offer.neoforge().equals(neo)&&state.values.get("inventory").equals(runtimeInventory(profile,loaded));}
 public static boolean runtimeMatchesStartup(State state,Path profile,Collection<Path> loaded,String mc,String neo,String startup)throws IOException{return startup!=null&&state.values.get("inventory").equals(startup)&&runtimeMatches(state,profile,loaded,mc,neo);}
 public static String runtimeInventory(Path profile,Collection<Path> loaded)throws IOException{
  Path mods=FirstLaunchFiles.safe(profile.resolve("mods"));if(!Files.isDirectory(mods))return FirstLaunchFiles.sha(new byte[0]);var rows=new TreeMap<String,String>();int bootstrap=0,count=0;
  try(var paths=Files.list(mods)){for(Path file:paths.toList()){FirstLaunchFiles.safe(file);if(!Files.isRegularFile(file)||!file.getFileName().toString().matches("[A-Za-z0-9][A-Za-z0-9._+\\-]{0,119}\\.jar")||++count>256||Files.size(file)>64L*1024*1024)return null;boolean found=false;for(Path p:loaded)try{if(Files.isSameFile(file,p)){found=true;break;}}catch(IOException ignored){}if(!found)return null;try(var jar=new ZipFile(file.toFile())){if(jar.getEntry("com/fixmer/mared/Mared.class")!=null){if(++bootstrap>1)return null;continue;}}rows.put("mods/"+file.getFileName(),FirstLaunchFiles.hash(file,64L*1024*1024));}}
  StringBuilder text=new StringBuilder();rows.forEach((p,h)->text.append(p).append('=').append(h).append('\n'));return FirstLaunchFiles.sha(text.toString().getBytes(StandardCharsets.US_ASCII));
 }
}
